        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    buildings += 1
                    q = deque([(r, c, 0)])
                    visited = {(r, c)}
                    while q:
                        cr, cc, d = q.popleft()
                        for dr, dc in dirs:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 0 and (nr, nc) not in visited:
