class Solution {
public:
    int shortestDistance(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> total_dist(m, vector<int>(n, 0));
        vector<vector<int>> reach_count(m, vector<int>(n, 0));
        int buildings = 0;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    buildings++;
                    vector<vector<bool>> visited(m, vector<bool>(n, false));
                    queue<tuple<int, int, int>> q;
                    q.push({r, c, 0});
                    visited[r][c] = true;
                    while (!q.empty()) {
                        auto [cr, cc, d] = q.front();
                        q.pop();
                        for (auto& dir : dirs) {
                            int nr = cr + dir[0], nc = cc + dir[1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 0 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                reach_count[nr][nc]++;
                                total_dist[nr][nc] += d + 1;
                                q.push({nr, nc, d + 1});
                            }
                        }
                    }
                }
            }
        }
        int ans = INT_MAX;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0 && reach_count[r][c] == buildings) {
                    ans = min(ans, total_dist[r][c]);
                }
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

class Solution {
    public int shortestDistance(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] totalDist = new int[m][n];
        int[][] reachCount = new int[m][n];
        int buildings = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    buildings++;
                    boolean[][] visited = new boolean[m][n];
                    Queue<int[]> q = new LinkedList<>();
                    q.offer(new int[]{r, c, 0});
                    visited[r][c] = true;
                    while (!q.isEmpty()) {
                        int[] top = q.poll();
                        int cr = top[0], cc = top[1], d = top[2];
                        for (int[] dir : dirs) {
                            int nr = cr + dir[0], nc = cc + dir[1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 0 && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                reachCount[nr][nc]++;
                                totalDist[nr][nc] += d + 1;
                                q.offer(new int[]{nr, nc, d + 1});
                            }
                        }
                    }
                }
            }
        }
        int ans = Integer.MAX_VALUE;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0 && reachCount[r][c] == buildings) {
                    ans = Math.min(ans, totalDist[r][c]);
                }
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

